# the Free Software Foundation, either version 3 of the License, or
# (at your option) any later version.

import math
import os
import random
from base64 import urlsafe_b64decode, urlsafe_b64encode
from binascii import hexlify, unhexlify

try:
    import gmpy2

    HAVE_GMP = True
except ImportError:  # pragma: no cover - environment dependent
    gmpy2 = None
    HAVE_GMP = False

try:
    from Crypto.Util import number

    HAVE_CRYPTO = True
except ImportError:  # pragma: no cover - environment dependent
    number = None
    HAVE_CRYPTO = False


_USE_MOD_FROM_GMP_SIZE = 1 << (8 * 2)
_USE_MULMOD_FROM_GMP_SIZE = 1 << 1000


def powmod(a, b, c):
    """Compute ``(a ** b) % c`` using GMP when available."""
    if a == 1:
        return 1
    if not HAVE_GMP or max(a, b, c) < _USE_MOD_FROM_GMP_SIZE:
        return pow(a, b, c)
    return int(gmpy2.powmod(a, b, c))


def mulmod(a, b, c):
    """Compute ``(a * b) % c`` using GMP when available."""
    if not HAVE_GMP or max(a, b, c) < _USE_MULMOD_FROM_GMP_SIZE:
        return (a * b) % c
    return int(gmpy2.mod(gmpy2.mul(gmpy2.mpz(a), gmpy2.mpz(b)), gmpy2.mpz(c)))


def extended_euclidean_algorithm(a, b):
    """Return ``(gcd, x, y)`` such that ``gcd == a*x + b*y``."""
    r0, r1 = a, b
    s0, s1 = 1, 0
    t0, t1 = 0, 1
    while r1:
        q = r0 // r1
        r0, r1 = r1, r0 - q * r1
        s0, s1 = s1, s0 - q * s1
        t0, t1 = t1, t0 - q * t1
    return r0, s0, t0


def invert(a, b):
    """Return the multiplicative inverse of ``a`` modulo ``b``."""
    if HAVE_GMP:
        inverse = int(gmpy2.invert(a, b))
        if inverse == 0:
            raise ZeroDivisionError("invert() no inverse exists")
        return inverse
    r, s, _ = extended_euclidean_algorithm(a, b)
    if r != 1:
        raise ZeroDivisionError("invert() no inverse exists")
    return s % b


def getprimeover(n_bits):
    """Return a random prime with at least ``n_bits`` bits."""
    if HAVE_GMP:
        randfunc = random.SystemRandom()
        candidate = gmpy2.mpz(randfunc.getrandbits(n_bits))
        candidate = gmpy2.bit_set(candidate, n_bits - 1)
        return int(gmpy2.next_prime(candidate))
    if HAVE_CRYPTO:
        return number.getPrime(n_bits, os.urandom)

    randfunc = random.SystemRandom()
    candidate = randfunc.randrange(2 ** (n_bits - 1), 2 ** n_bits) | 1
    while not is_prime(candidate):
        candidate += 2
    return candidate


def isqrt(n):
    """Return the integer square root of ``n``."""
    if HAVE_GMP:
        return int(gmpy2.isqrt(n))
    return improved_i_sqrt(n)


def improved_i_sqrt(n):
    """Compute the integer square root of a non-negative integer."""
    assert n >= 0
    if n == 0:
        return 0

    i = n.bit_length() >> 1
    m = 1 << i
    while (m << i) > n:
        m >>= 1
        i -= 1

    diff = n - (m << i)
    for k in range(i - 1, -1, -1):
        j = 1 << k
        new_diff = diff - (((m << 1) | j) << k)
        if new_diff >= 0:
            diff = new_diff
            m |= j
    return m


def base64url_encode(payload):
    """Encode bytes or text using URL-safe base64 without padding."""
    if not isinstance(payload, bytes):
        payload = payload.encode("utf-8")
    encoded = urlsafe_b64encode(payload)
    return encoded.decode("utf-8").rstrip("=")


def base64url_decode(payload):
    """Decode a URL-safe base64 string that may omit padding."""
    remainder = len(payload) % 4
    if remainder == 2:
        payload += "=="
    elif remainder == 3:
        payload += "="
    elif remainder != 0:
        raise ValueError("Invalid base64 string")
    return urlsafe_b64decode(payload.encode("utf-8"))


def base64_to_int(source):
    """Convert a URL-safe base64 string into an integer."""
    return int(hexlify(base64url_decode(source)), 16)


def int_to_base64(source):
    """Convert a positive integer into a URL-safe base64 string."""
    assert source != 0
    value = hex(source).rstrip("L").lstrip("0x")
    return base64url_encode(unhexlify((len(value) % 2) * "0" + value))


def _generate_first_primes(count=2048):
    primes = []
    candidate = 2
    while len(primes) < count:
        is_candidate_prime = True
        limit = int(math.isqrt(candidate))
        for prime in primes:
            if prime > limit:
                break
            if candidate % prime == 0:
                is_candidate_prime = False
                break
        if is_candidate_prime:
            primes.append(candidate)
        candidate = 3 if candidate == 2 else candidate + 2
    return primes


first_primes = _generate_first_primes()


def miller_rabin(n, k):
    """Run the Miller-Rabin primality test on ``n`` for ``k`` rounds."""
    assert n > 3

    d = n - 1
    r = 0
    while d % 2 == 0:
        d //= 2
        r += 1

    for _ in range(k):
        a = random.randint(2, n - 2)
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(1, r):
            x = (x * x) % n
            if x == n - 1:
                break
        else:
            return False
    return True


def is_prime(n, mr_rounds=25):
    """Return whether ``n`` is prime with overwhelming probability."""
    if n <= first_primes[-1]:
        return n in first_primes
    for prime in first_primes:
        if n % prime == 0:
            return False
    return miller_rabin(n, mr_rounds)


__all__ = [
    "HAVE_CRYPTO",
    "HAVE_GMP",
    "base64_to_int",
    "base64url_decode",
    "base64url_encode",
    "extended_euclidean_algorithm",
    "first_primes",
    "getprimeover",
    "improved_i_sqrt",
    "int_to_base64",
    "invert",
    "is_prime",
    "isqrt",
    "miller_rabin",
    "mulmod",
    "powmod",
]

