"""Toy example of aggregating encrypted client updates."""

from phe import generate_paillier_keypair


def encrypted_average(updates):
    public_key, private_key = generate_paillier_keypair(n_length=256)
    encrypted_updates = [public_key.encrypt(update) for update in updates]
    total = sum(encrypted_updates)
    return private_key.decrypt(total / len(updates))


