"""Toy encrypted inference for a linear model."""

from phe import generate_paillier_keypair


def encrypted_linear_score(features, weights, bias):
    public_key, private_key = generate_paillier_keypair(n_length=256)
    encrypted_score = public_key.encrypt(bias)
    for feature, weight in zip(features, weights):
        encrypted_score += public_key.encrypt(feature) * weight
    return private_key.decrypt(encrypted_score)


if __name__ == "__main__":
    features = [0.5, -1.0, 2.0]
    weights = [0.2, 0.7, -0.4]
    bias = 0.1
    print(encrypted_linear_score(features, weights, bias))
